import { Router } from "express";
import type { Request, Response } from "express";
import type { AddTaskUseCase } from "../../application/use-cases/add-task-use-case";
import type { AssignTaskUseCase } from "../../application/use-cases/assign-task-use-case";
import type { ListProjectTasksUseCase } from "../../application/use-cases/list-project-tasks-use-case";
import type { MarkTaskDoneUseCase } from "../../application/use-cases/mark-task-done-use-case";
import { optionalString, queryString, requiredString } from "./request-fields";

export class TaskController {
  constructor(
    private readonly addTask: AddTaskUseCase,
    private readonly assignTask: AssignTaskUseCase,
    private readonly listProjectTasks: ListProjectTasksUseCase,
    private readonly markTaskDone: MarkTaskDoneUseCase,
  ) {}

  routes(): Router {
    const router = Router();
    router.post("/projects/:projectId/tasks", (req, res) => this.add(req, res));
    router.get("/projects/:projectId/tasks", (req, res) => this.list(req, res));
    router.put("/tasks/:taskId/assignee", (req, res) => this.assign(req, res));
    router.post("/tasks/:taskId/done", (req, res) => this.done(req, res));
    return router;
  }

  private add(req: Request, res: Response): void {
    const task = this.addTask.execute({
      projectId: String(req.params["projectId"]),
      title: requiredString(req.body, "title"),
      description: optionalString(req.body, "description") ?? "",
      dueDate: optionalString(req.body, "dueDate"),
      status: optionalString(req.body, "status"),
    });
    res.status(201).json(task);
  }

  private list(req: Request, res: Response): void {
    const tasks = this.listProjectTasks.execute({
      projectId: String(req.params["projectId"]),
      status: queryString(req.query["status"]),
      assigneeId: queryString(req.query["assigneeId"]),
    });
    res.json(tasks);
  }

  private assign(req: Request, res: Response): void {
    const task = this.assignTask.execute({
      taskId: String(req.params["taskId"]),
      assigneeId: requiredString(req.body, "assigneeId"),
    });
    res.json(task);
  }

  private done(req: Request, res: Response): void {
    res.json(this.markTaskDone.execute(String(req.params["taskId"])));
  }
}

